import styled from "styled-components";

    
export const ListingContainer= styled.div`
    width:100vw;
    display:flex;
    flex-direction: column;
    align-items: center;

    @media screen and (min-width: 1024px){
        align-items: center;

        width:90;
        
        
    }

`
export const SearchContainer = styled.div`
    width:70%;
    height: 46px;
    margin-top: 1.5rem;

    background: ${({theme}) => theme.colors.background};
    border:1px solid ${({theme}) => theme.colors.secondary};

   
  



    display:flex;
    justify-content: space-between;
    z-index: 5000;

    input{
        font-size: 0.75rem;
        font-weight: 400;
        background: transparent;
        border: 0;
        width: 80%;
        padding-left:1rem;
    
        
    }

    button{
        width:20%;
        height:46px;
        
        color: ${({theme}) => theme.colors.background};
        background: ${({theme}) => theme.colors.primary}; 
        border: 1px solid ${({theme}) => theme.colors.primary};
        border-radius: 1px;
    
     
    
        display:flex;
        justify-content: center;
        align-items: center;
        
        z-index: 5000;
    
       &:hover{
           filter: opacity(0.8)
       }
       &:disabled{
        filter: opacity(0.4)
    }
    }

    @media screen and (min-width: 1024px){
        width: 40%;
       
        
        button{
            width:10%;
        }
    }

`

export const BodyListing = styled.div`
    width: 90%;
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-top: 1rem;
    position: relative;

    @media screen and (min-width: 1024px) {  
        width: 85%;
        flex-direction: row;
        flex-wrap: wrap;

       
       
        justify-content: space-between;

    }

 
  

`
